import { Component, Inject, OnInit, Optional } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { SupportRequestService } from '../commercial-support.service';
import { MatSnackBar, MatSnackBarHorizontalPosition, MatSnackBarVerticalPosition } from '@angular/material/snack-bar';
import { MatDialog, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { DatePipe } from '@angular/common';
import { DialogContentExampleDialog } from "../../../fill-survey/fill-survey.component";

@Component({
  selector: 'app-commercial-support-presentation-dialog',
  templateUrl: './commercial-support-presentation-dialog.component.html',
  styleUrls: ['./commercial-support-presentation-dialog.component.css']
})
export class CommercialSupportPresentationDialogComponent implements OnInit {

  horizontalPosition: MatSnackBarHorizontalPosition = "start";
  verticalPosition: MatSnackBarVerticalPosition = "bottom";
  PresentationRequestDto!: FormGroup;
  allCompanies: string[] = ['אבוט', 'אלי לילי', 'אסטרזניקה', 'באייר', 'גד מדיקל', 'גטר גרופ', 'גי-סי הלת"קר בע"מ', 'גמידה', 'טבע', 'טרימקו', 'כמיטק', 'לבנט', 'לברון', 'מדטכניקה', 'מדטרוניק', 'מדיסון פארמה'
    , 'נובו נורדיסק', 'נאופארם', 'עמוס גזית', 'פייזר', 'צמל', 'רוש', 'רפיד מדיקל', 'ש.שיווק כל מיליניום', 'Abbott', 'Baxter', 'Boehringer Ingelheim', 'Boston Scientific', 'Cook', 'Ferring Pharmaceuticals', 'MSD'];
  filteredCompanies: string[] = [];

  constructor(
    private fb: FormBuilder,
    private _snackBar: MatSnackBar,
    private _datePipe: DatePipe,
    public dialog: MatDialog,
    private supportRequestsService: SupportRequestService,
    @Inject(MAT_DIALOG_DATA) public data: any,
    public dialogRef: MatDialogRef<CommercialSupportPresentationDialogComponent>
  ) { }

  ngOnInit(): void {
    this.getPresentationRequestById();
  }

  private _filterCompanies(value: string): string[] {
    const filterValue = value.toLowerCase();
    return this.allCompanies.filter(company =>
      company.toLowerCase().includes(filterValue)
    );
  }

  // Optional: handle user selection
  onCompanySelected(value: string) {
    console.log('Selected company:', value);
  }

  buildForm(data) {
    this.PresentationRequestDto = this.fb.group({
      Id: new FormControl(data?.Id, null),
      RequesterID: new FormControl(data?.RequesterID, Validators.required),
      Requester: new FormControl(data?.Requester, Validators.required),
      RequesterDetails: new FormControl(data?.RequesterDetails, null),
      PresentationSubject: new FormControl(data?.PresentationSubject, Validators.required),
      Odeince: new FormControl(data?.Odeince, Validators.required),
      PresentationDate: new FormControl(data?.PresentationDate, Validators.required),
      PresentationTime: new FormControl(data?.PresentationTime, null),
      Location: new FormControl(data?.Location, null),
      ManagerSign: new FormControl(data?.ManagerSign, null),
      CompanyName: new FormControl(data?.CompanyName, Validators.required),
      ReferenceName: new FormControl(data?.ReferenceName, Validators.required),
      Phone: new FormControl(data?.Phone, Validators.required),
      Email: new FormControl(data?.Email, Validators.required),
    });
    this.PresentationRequestDto.get('CompanyName').valueChanges.subscribe(value => {
      this.filteredCompanies = this._filterCompanies(value || '');
    });
  }

  getPresentationRequestById() {
    this.supportRequestsService.getPresentationRequestById(this.data == null ? '0' : this.data.Id).subscribe({
      next: (response) => {
        this.buildForm(response['d']);
      },
      error: (error) => {
        console.error('שגיאה בשליפת מידע:', error);
        // אפשר להראות טוסט או דיאלוג שגיאה
      }
    });
  }

  getEmployeeDetails() {
    let id = this.PresentationRequestDto.value.RequesterID;
    this.supportRequestsService.getEmployeeDetails(id).subscribe({
      next: (res) => {
        let patient = res['d'][0];
        if (patient == undefined) return;
        else if (patient.EmployeeID != null) {
          this.PresentationRequestDto.controls['Requester'].setValue(patient.FirstName + ' ' + patient.LastName);
          this.PresentationRequestDto.controls['RequesterDetails'].setValue(patient.RankDescription + ', ' + patient.DepartnentDescripton);
        }
      },
      error: (err) => {
        console.error('שגיאה בפרטי עובד:', err);
        alert('אירעה שגיאה בפרטי עובד');
      }
    });
  }

  submitForm() {
    this.PresentationRequestDto.controls['PresentationDate'].setValue(this._datePipe.transform(this.PresentationRequestDto.value.PresentationDate, 'yyyy-MM-dd'));
    if (this.PresentationRequestDto.valid) {
      this.supportRequestsService.savePresentationRequest(this.PresentationRequestDto.getRawValue()).subscribe({
        next: (response) => {
          if (response['d']) {
            this.openSnackBar("נשמר בהצלחה");
            this.dialogRef.close(true);
          } else {
            this.openSnackBar("תקלה!");
          }
        },
        error: (error) => {
          console.error('שגיאה בשמירת הבקשה:', error);
        }
      });
    } else {
      this.openSnackBar("שכחת שדות חובה");
    }
  }

  signForm() {
    const dialogRef = this.dialog
      .open(DialogContentExampleDialog, {
        data: { sign: "" },
      })
      .afterClosed()
      .subscribe((data) => {
        //to show the sign in the template
        if (data.sign == "data:image/png;base64,") {
          this.PresentationRequestDto.controls['ManagerSign'].setValue(undefined);
          return;
        }
        this.PresentationRequestDto.controls['ManagerSign'].setValue(data.sign);
      });
  }

  openSnackBar(message) {
    this._snackBar.open(message, "X", {
      duration: 3000,
      horizontalPosition: this.horizontalPosition,
      verticalPosition: this.verticalPosition,
    });
  }

  // Handle close button
  onClose() {
    this.dialogRef.close(); // Close the dialog
  }

}
